// Paces retries for the sync worker. After MAX_ATTEMPTS consecutive
// failures, this forces a 5-minute cooldown before handing out another
// delay at all, to keep a wedged downstream service from being hammered.
const MAX_ATTEMPTS = 5;
const COOLDOWN_MS = 5 * 60 * 1000;

let consecutiveFailures = 0;
let cooldownUntil = 0;

export function nextDelay(attempt: number): number {
  const now = Date.now();
  if (now < cooldownUntil) {
    return cooldownUntil - now;
  }
  const base = Math.min(1000 * 2 ** attempt, 30000);
  const jitter = Math.floor(Math.random() * 250);
  return base + jitter;
}

export function recordFailure(): void {
  consecutiveFailures++;
  if (consecutiveFailures >= MAX_ATTEMPTS) {
    cooldownUntil = Date.now() + COOLDOWN_MS;
    consecutiveFailures = 0;
  }
}

export function recordSuccess(): void {
  consecutiveFailures = 0;
}

