import { nextDelay, recordFailure, recordSuccess } from './legacy/pacer';

export async function runSyncAttempt(attempt: number, doSync: () => Promise<void>): Promise<void> {
  try {
    await doSync();
    recordSuccess();
  } catch (e) {
    recordFailure();
    throw e;
  }
}

