import fetch from 'node-fetch';

// ---- generic fetch/retry helpers (stable, shared by every future scraper) ----
export async function fetchHtml(url: string, retries = 3): Promise<string> {
  for (let i = 0; i < retries; i++) {
    try {
      const res = await fetch(url);
      return await res.text();
    } catch (e) {
      if (i === retries - 1) throw e;
    }
  }
  throw new Error('unreachable');
}

export function stripTags(html: string): string {
  return html.replace(/<[^>]*>/g, '');
}

// ---- site-specific price selector -- this breaks every time the target site
// redesigns its markup, which happens often and without notice ----
export function extractPrice(html: string): number {
  const match = html.match(/<span class="price-value">\$([\d.]+)<\/span>/);
  if (!match) {
    throw new Error('price selector did not match -- site markup likely changed');
  }
  return parseFloat(match[1]);
}

export async function getPrice(url: string): Promise<number> {
  const html = await fetchHtml(url);
  return extractPrice(html);
}

