export interface WebhookEvent {
  provider: string;
  type: string;
  payload: unknown;
}

// ---- generic dispatch machinery (stable) ----
const handlers = new Map<string, (event: WebhookEvent) => void>();

export function registerHandler(type: string, fn: (event: WebhookEvent) => void): void {
  handlers.set(type, fn);
}

export function dispatch(event: WebhookEvent): void {
  const fn = handlers.get(event.type);
  if (fn) fn(event);
}

// ---- provider payload mapping -- Stripe and GitHub both restructure their
// webhook payload shapes multiple times a year without warning; this mapping
// gets rewritten every time one of them does ----
export function normalizePayload(provider: string, raw: any): WebhookEvent {
  if (provider === 'stripe') {
    return { provider, type: raw.type, payload: raw.data.object };
  }
  if (provider === 'github') {
    return { provider, type: raw.action, payload: raw };
  }
  throw new Error(`unknown provider ${provider}`);
}

// ---- retry helper (stable) ----
export function withRetry<T>(fn: () => T, retries = 3): T {
  let lastErr: unknown;
  for (let i = 0; i < retries; i++) {
    try {
      return fn();
    } catch (e) {
      lastErr = e;
    }
  }
  throw lastErr;
}

